from collections import deque

def comps8(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if not g[r][c] or (r,c) in seen: continue
   color=g[r][c]; q=[(r,c)]; seen.add((r,c)); a=[]
   while q:
    y,x=q.pop(); a.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      p=(y+dy,x+dx)
      if 0<=p[0]<h and 0<=p[1]<w and p not in seen and g[p[0]][p[1]]==color: seen.add(p);q.append(p)
   out.append(a)
 return out

